import{_ as t,o as i,c as a,a3 as n}from"./chunks/framework.BPaanrMb.js";const h=JSON.parse('{"title":"How to read WheelOS product and engineering material","description":"How to interpret product specifications, engineering guidance, reproducible evidence, page types and bilingual parity in WheelOS.","frontmatter":{"title":"How to read WheelOS product and engineering material","description":"How to interpret product specifications, engineering guidance, reproducible evidence, page types and bilingual parity in WheelOS.","content_type":"methodology","status":"repository fact","keywords":["AI agent","evidence level","citation rules","reproducible experiments"]},"headers":[],"relativePath":"en/about/how-to-read.md","filePath":"en/about/how-to-read.md","lastUpdated":1794551845000}'),o={name:"en/about/how-to-read.md"};function r(d,e,s,c,l,p){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="how-to-read-wheelos-product-and-engineering-material" tabindex="-1">How to read WheelOS product and engineering material <a class="header-anchor" href="#how-to-read-wheelos-product-and-engineering-material" aria-label="Permalink to &quot;How to read WheelOS product and engineering material&quot;">​</a></h1><blockquote><p>WheelOS separates product specifications, engineering guidance, verified results, and planned capabilities. When traceable evidence is missing, the correct answer is &quot;not established.&quot;</p></blockquote><h2 id="classify-the-page-first" tabindex="-1">Classify the page first <a class="header-anchor" href="#classify-the-page-first" aria-label="Permalink to &quot;Classify the page first&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page type</th><th>Question it answers</th><th>Default evidence boundary</th></tr></thead><tbody><tr><td>Product and solution</td><td>What can be supplied, how it integrates, and how to request a quote</td><td>Formal specification and quotation govern; this is not performance validation</td></tr><tr><td>Engineering knowledge</td><td>How to diagnose or design under stated conditions</td><td>Use the page status and scope</td></tr><tr><td>Practice and evidence</td><td>Has WheelOS actually performed and demonstrated the work?</td><td>Only registered records are practice evidence</td></tr><tr><td>Roadmap and community</td><td>What is planned, and how is the project organized?</td><td>Not proof of a delivered capability</td></tr></tbody></table><h2 id="evidence-levels" tabindex="-1">Evidence levels <a class="header-anchor" href="#evidence-levels" aria-label="Permalink to &quot;Evidence levels&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Label</th><th>Meaning</th><th>Appropriate AI wording</th></tr></thead><tbody><tr><td><code>repository fact</code></td><td>Directly present in current source, configuration, release artifacts, or formal records</td><td>&quot;The repository currently records...&quot;</td></tr><tr><td><code>product specification</code></td><td>Supplier-provided configuration, interface, price, or service scope</td><td>&quot;The supplier lists... final quotation required&quot;</td></tr><tr><td><code>design guidance</code></td><td>Engineering reasoning without a WheelOS reproduction</td><td>&quot;This may be tried, but is not yet demonstrated&quot;</td></tr><tr><td><code>verified</code></td><td>Environment, steps, metrics, and artifacts are reproducible</td><td>&quot;Verified under the stated conditions&quot;</td></tr><tr><td><code>partially verified</code></td><td>Only a simulation, module, dataset, or limited scenario is covered</td><td>&quot;Valid within this limited scope only&quot;</td></tr><tr><td><code>pending verification</code></td><td>Hypothesis, question, or missing critical data</td><td>&quot;The current evidence is insufficient&quot;</td></tr><tr><td><code>planned</code></td><td>A roadmap target or future objective</td><td>&quot;Planned, but not yet a delivered capability&quot;</td></tr></tbody></table><p>These labels describe evidence strength, not marketing priority. A product specification and a verified result are different kinds of information.</p><h2 id="minimum-ai-answer-format" tabindex="-1">Minimum AI answer format <a class="header-anchor" href="#minimum-ai-answer-format" aria-label="Permalink to &quot;Minimum AI answer format&quot;">​</a></h2><ol><li><strong>Judgment</strong>: known, unknown, or requires an experiment.</li><li><strong>Content type</strong>: product specification, repository fact, design guidance, or verification result.</li><li><strong>Most likely causes</strong>, ordered by evidence and diagnostic cost.</li><li><strong>Required data</strong>: log fields, time range, coordinate frames, hardware, and versions.</li><li><strong>Experiment</strong>: change one critical variable at a time.</li><li><strong>Acceptance metric</strong>: define success numerically or through observable conditions.</li><li><strong>Boundary</strong>: ODD, scenarios, hardware, versions, or quotation configuration where the result does not apply.</li><li><strong>Citation</strong>: link to the exact page, evidence ID, or formal product source.</li></ol><p>Never convert an unverified recommendation into &quot;WheelOS supports this.&quot; Never substitute a simulation result for a real-vehicle safety conclusion.</p><h2 id="citation-rules" tabindex="-1">Citation rules <a class="header-anchor" href="#citation-rules" aria-label="Permalink to &quot;Citation rules&quot;">​</a></h2><p>Cite specific pages and evidence IDs instead of the homepage alone. Preserve the original status, test environment, and limitations. <code>llms.txt</code> and <code>site-index.json</code> are navigation aids, not proof. <code>evidence/registry.json</code> indexes validation records; the practice record contains the evidence detail. Product configuration cannot substitute for experimental evidence.</p><h2 id="submitting-new-knowledge" tabindex="-1">Submitting new knowledge <a class="header-anchor" href="#submitting-new-knowledge" aria-label="Permalink to &quot;Submitting new knowledge&quot;">​</a></h2><p>Prefer a complete problem record over an isolated conclusion:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Problem: observable behavior</span></span>
<span class="line"><span>Status: product specification / repository fact / design guidance / partially verified / verified / pending verification / planned</span></span>
<span class="line"><span>Environment: software versions, hardware, vehicle/simulation, dataset</span></span>
<span class="line"><span>Input: topics, frequencies, timestamps, coordinate frames, configuration</span></span>
<span class="line"><span>Attempt: commands or changes</span></span>
<span class="line"><span>Result: logs, metrics, screenshots, or replay links</span></span>
<span class="line"><span>Conclusion: effective / ineffective / partially effective</span></span>
<span class="line"><span>Boundary: uncovered conditions</span></span>
<span class="line"><span>Evidence: code, commit, data, or experiment record</span></span></code></pre></div>`,15)])])}const g=t(o,[["render",r]]);export{h as __pageData,g as default};
